(() => {
  'use strict';
  const data = window.PORTFOLIO, main = document.querySelector('main');
  const esc = value => String(value).replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const tags = values => `<div class="tags">${values.map(x => `<span class="tag">${esc(x)}</span>`).join('')}</div>`;
  const eyebrow = text => `<div class="eyebrow"><span class="dot"></span>${esc(text)}</div>`;
  const safeUrl = value => {try {const u = new URL(value);return u.protocol === 'https:' ? u.href : '';} catch {return '';}};
  function figure(type) {
    let svg;
    if(type === 'collision') svg = `<path d="M18 86C59 86 71 37 111 37S166 84 193 84M18 42C55 42 82 89 120 89S162 43 193 43" fill="none" stroke="#475569" stroke-width="2"/><path d="M18 65H193" stroke="#c1c5ca" stroke-dasharray="3 5"/><circle cx="109" cy="63" r="24" fill="none" stroke="#c1c5ca" stroke-dasharray="3 3"/><path d="M106 34l8 3-8 3M113 86l-8 3 8 3" fill="none" stroke="#475569" stroke-width="1.5"/><circle cx="23" cy="85" r="4" fill="#475569"/><circle cx="188" cy="43" r="4" fill="#7b8189"/>`;
    else if(type === 'simulation') svg = `<g fill="none" stroke="#b9bfc6"><path d="M20 20v85h174"/><path d="M20 65H194" stroke-dasharray="3 4"/></g><path d="M21 81L43 39L63 75L82 52L99 68L122 59L144 63L192 63" fill="none" stroke="#b9bfc6" stroke-width="1.5"/><path d="M21 83C40 76 39 32 62 56S87 75 104 61S133 64 152 63H192" fill="none" stroke="#475569" stroke-width="2"/><g font-family="monospace" font-size="8" fill="#727981"><text x="30" y="26">sensor / state</text><text x="184" y="117">t</text></g>`;
    else svg = `<g fill="none" stroke="#c6cbd1"><path d="M27 103L188 103M47 114V17"/><ellipse cx="123" cy="64" rx="58" ry="30" transform="rotate(-25 123 64)" stroke-dasharray="3 4"/></g><path d="M46 100C67 111 42 43 97 33S191 32 157 76S95 85 118 62S145 63 130 66" fill="none" stroke="#475569" stroke-width="2"/><circle cx="130" cy="66" r="3" fill="#475569"/><g font-family="monospace" font-size="8" fill="#727981"><text x="32" y="19">x₂</text><text x="187" y="117">x₁</text></g>`;
    return `<div class="mini-figure"><svg viewBox="0 0 210 130" role="img" aria-label="${type === 'collision'?'충돌회피 경로':type === 'simulation'?'센서 신호와 상태 비교':'폐루프 상태 흐름'} 개념도">${svg}</svg></div>`;
  }
  function projectRow(p) {return `<a class="project-row" href="#research/${esc(p.id)}"><span class="project-number">${p.number}</span><div><div class="project-kicker">${esc(p.type)}</div><h3>${esc(p.koreanTitle)}</h3><p class="project-sub">${esc(p.type.toLowerCase())}</p>${tags(p.tags)}</div><span class="project-open" aria-hidden="true">→</span></a>`;}
  function noteCard(n) {return `<a class="note-card" href="#notes/${esc(n.slug)}"><div class="note-meta"><span class="note-category">${esc(n.category.toUpperCase())}</span><span>${esc(n.status)} · ${esc(n.read)}</span></div><h3>${esc(n.title)}</h3><p>${esc(n.summary)}</p><div class="note-bottom">${tags(n.tags)}<span class="arrow" aria-hidden="true">↗</span></div></a>`;}
  function overview() {return `<div class="wrap"><section class="hero"><div>${eyebrow('Personal website')}<h1>${esc(data.profile.name)}</h1><p class="hero-subtitle">Aerospace engineering · Guidance, navigation & control</p><p class="hero-intro">${esc(data.profile.intro)}</p><div class="hero-links"><a class="button" href="#research">Explore research <span>↗</span></a><a class="text-link" href="#cv">View my CV ↗</a></div></div></section><div class="interest-strip"><span class="eyebrow">RESEARCH INTERESTS</span><div class="interest-items">${data.profile.interests.map(x=>`<span>${esc(x)}</span>`).join('')}</div></div><section class="section"><div class="section-heading"><div>${eyebrow('01 / Selected work')}<h2>Research & projects</h2></div><p>동역학 모델링에서 제어기 구현까지.<br>문제를 정의하고 결과를 검증하는 과정입니다.</p></div>${data.projects.map(projectRow).join('')}<a class="text-link" href="#research">프로젝트 자세히 보기 ↗</a></section></div><section class="section section-shade"><div class="wrap"><div class="section-heading"><div>${eyebrow('02 / Learning in public')}<h2>Study notes</h2></div><a class="text-link" href="#notes">All study notes ↗</a></div><div class="note-grid">${data.notes.slice(0,4).map(noteCard).join('')}</div></div></section><div class="wrap"><section class="section about-section"><div>${eyebrow('03 / About me')}<h2>Eoram Kim</h2><p>항공우주 시스템을 수식으로 이해하고 코드로 구현합니다. 실험 조건과 검증 과정을 남기며 배운 내용을 다음 문제에 연결하고자 합니다.</p><div class="hero-links"><a class="text-link" href="#cv">Education & experience ↗</a></div></div><div><div class="about-detail"><span>EDUCATION</span><span>인하대학교 · 항공우주공학 전공</span></div><div class="about-detail"><span>RESEARCH</span><span>항공우주제어시스템 연구실<br>학부연구생으로 연구 과제 참여</span></div><div class="about-detail"><span>TOOLKIT</span><span>Python · MATLAB / Simulink<br>ROS 2 · Gazebo · Optimization</span></div><div class="about-detail"><span>INTERESTS</span><span>유도·항법·제어 · MPC · 동역학 학습</span></div></div></section></div>`;}
  function research(id) {
    const chosen = id ? data.projects.filter(p=>p.id===id) : data.projects;
    if(!chosen.length) return notFound();
    return `<div class="wrap"><div class="page-intro">${eyebrow('Research / Projects')}<h1>Research & projects</h1><p>모델링, 최적화, 구현, 검증. 연구와 프로젝트에서 다룬 문제를 정리합니다.</p></div>${id?'<a class="back" href="#research">← 모든 프로젝트</a>':''}${chosen.map(p=>`<section class="project-detail"><div><div class="project-kicker">${p.number} / ${esc(p.type)}</div><h2>${esc(p.koreanTitle)}</h2><p>${esc(p.description)}</p><ul>${p.focus.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${tags(p.tags)}</div><div>${figure(p.figure)}<p class="figure-caption">${esc(p.note)}<br>Figure: conceptual illustration.</p></div></section>`).join('')}<div class="article-foot"><span>프로젝트의 실험 결과와 코드 링크는 검증 후 추가할 예정입니다.</span><a href="#notes">관련 공부 기록 ↗</a></div></div>`;
  }
  let selectedFilter='All', query='';
  function archive() {return `<div class="wrap archive"><div class="page-intro">${eyebrow('Study archive')}<h1>Study notes</h1><p>제어, 동역학 학습, 최적화, 시뮬레이션에서 배운 내용을 정리합니다. 현재 글은 검토와 확장을 위한 초안입니다.</p></div><label class="searchbar"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/></svg><input id="note-search" type="search" value="${esc(query)}" placeholder="제목, 키워드, 태그로 검색…" aria-label="학습 기록 검색"></label><div class="filters" aria-label="학습 기록 분류">${['All',...new Set(data.notes.map(n=>n.category))].map(c=>`<button class="filter ${c===selectedFilter?'active':''}" type="button" data-filter="${esc(c)}" aria-pressed="${c===selectedFilter}">${esc(c==='All'?'All notes':c)}</button>`).join('')}</div><p id="results-count" class="results-count" role="status" aria-live="polite"></p><div id="note-results" class="note-grid"></div></div>`;}
  function filterNotes() {
    const result=data.notes.filter(n=>(selectedFilter==='All'||n.category===selectedFilter)&&[n.title,n.summary,n.category,...n.tags,...n.sections.map(s=>s.text||'')].join(' ').toLocaleLowerCase().includes(query.trim().toLocaleLowerCase()));
    document.getElementById('results-count').textContent=`${result.length} / ${data.notes.length} NOTES`;
    document.getElementById('note-results').innerHTML=result.length?result.map(noteCard).join(''):'<p class="empty">일치하는 기록이 없습니다. 다른 검색어 또는 분류를 선택해 주세요.</p>';
    document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===selectedFilter);b.setAttribute('aria-pressed',String(b.dataset.filter===selectedFilter));});
  }
  function article(slug) {
    const n=data.notes.find(x=>x.slug===slug);if(!n)return notFound();
    document.title=`${n.title} — Eoram Kim`;
    return `<div class="wrap"><article class="article"><a class="back" href="#notes">← Study archive</a>${eyebrow(`${n.category} / ${n.status} / ${n.read}`)}<h1>${esc(n.title)}</h1><p class="lead">${esc(n.summary)}</p><div class="article-tags">${tags(n.tags)}</div><div class="article-content">${n.sections.map(s=>`<section><h2>${esc(s.heading)}</h2>${s.text?`<p>${esc(s.text)}</p>`:''}${s.formula?`<div class="formula" role="math" aria-label="${esc(s.formula)}">${esc(s.formula)}</div>`:''}${s.list?`<ul>${s.list.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}</section>`).join('')}</div><div class="article-foot"><span>학습 내용 정리를 위한 초안 · Eoram Kim</span><a href="#notes">다른 노트 읽기 ↗</a></div></article></div>`;
  }
  function cv() {return `<div class="wrap"><div class="page-intro">${eyebrow('Curriculum vitae')}<h1>Eoram Kim</h1><p>Eoram Kim · 항공우주공학 · 유도·항법·제어</p></div><div class="cv-layout"><aside class="cv-sidebar"><a class="button" href="./cv.html">Printable CV <span>↗</span></a><p>인쇄용 페이지에서 브라우저의 인쇄 기능으로 PDF를 저장할 수 있습니다.</p><p style="margin-top:15px">기간·학적 상태·연락처를 확인한 뒤 최종 CV로 사용하세요.</p>${contact()}</aside><div><section class="cv-group"><h2>Education</h2><div class="cv-item"><h3>인하대학교 · 항공우주공학 전공</h3><p>항공우주 시스템 및 제어 분야 학습</p></div><div class="cv-item"><h3>주요 수강 과목</h3><p>인공위성 시스템 · A+<br>우주항공 데이터분석 및 머신러닝 (대학원 과목) · A+</p></div></section><section class="cv-group"><h2>Research experience</h2><div class="cv-item"><h3>인하대학교 항공우주제어시스템 연구실</h3><p>학부연구생으로 연구 과제 참여</p><ul><li>다수 무인체의 협력적 충돌회피와 정면 접근 문제 연구</li><li>재사용발사체 자율 귀환 및 착륙 관련 KARI 위탁과제 참여: 운용 페이즈와 제약 정리</li><li>QENDy 모델과 선형화 MPC의 구현 및 비교 연구</li></ul></div></section><section class="cv-group"><h2>Selected projects</h2>${data.projects.map(p=>`<div class="cv-item"><h3><a href="#research/${esc(p.id)}">${esc(p.koreanTitle)} ↗</a></h3><p>${esc(p.focus[0])}</p></div>`).join('')}</section><section class="cv-group"><h2>Technical skills</h2><div class="cv-skills"><span>PROGRAMMING</span><span>Python · NumPy · SciPy · MATLAB</span></div><div class="cv-skills"><span>CONTROL</span><span>MPC · CVXPY · OSQP · Simulink</span></div><div class="cv-skills"><span>ROBOTICS</span><span>ROS 2 · Gazebo · Ubuntu</span></div><div class="cv-skills"><span>ML & DATA</span><span>PyTorch · JAX · 데이터 분석</span></div></section><section class="cv-group"><h2>Qualifications & activities</h2><div class="cv-item"><h3>ADsP · OPIc IH</h3><p>데이터분석 준전문가 · 영어 말하기 평가</p></div><div class="cv-item"><h3>로봇항공기 대회 팀장</h3><p>11명 팀의 프로젝트 운영 및 예산 관리</p></div><div class="cv-item"><h3>MACH 밴드 · 연습부장 활동</h3><p>합주와 연습 운영</p></div></section></div></div></div>`;}
  function contact(){const github=safeUrl(data.profile.github);const email=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.profile.email)?data.profile.email:'';return `<div style="margin-top:20px">${github?`<p><a href="${esc(github)}" target="_blank" rel="noopener noreferrer">GitHub ↗</a></p>`:''}${email?`<p><a href="mailto:${esc(email)}">${esc(email)}</a></p>`:''}</div>`;}
  function notFound(){return `<div class="wrap"><section class="page-intro"><h1>페이지를 찾을 수 없습니다.</h1><p>링크가 변경되었거나 아직 추가되지 않은 기록입니다.</p><div class="hero-links"><a class="button" href="#home">홈으로 이동 ↗</a></div></section></div>`;}
  function render(moveFocus=false) {
    const route=location.hash.slice(1)||'home';const [page,id]=route.split('/');
    document.title='Eoram Kim — Aerospace & Control';
    main.innerHTML=page==='home'?overview():page==='research'?research(id):page==='notes'?(id?article(id):archive()):page==='cv'?cv():notFound();
    document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===page);if(a.dataset.nav===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
    if(page==='notes'&&!id){filterNotes();document.getElementById('note-search').addEventListener('input',e=>{query=e.target.value;filterNotes();});document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{selectedFilter=b.dataset.filter;filterNotes();}));}
    if(moveFocus){window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}
  }
  document.getElementById('year').textContent=new Date().getFullYear();
  const github=safeUrl(data.profile.github);if(github){const link=document.getElementById('github-link');link.href=github;link.target='_blank';link.rel='noopener noreferrer';link.hidden=false;}
  window.addEventListener('hashchange',()=>render(true));render();
})();
